def render_mascot(grid: Grid, bg_threshold: int = 35) -> Group:
    """Render a pixel grid (16x16, 24x24, etc.) into an (N/2)-line Rich Group using half blocks."""
    lines = []
    num_rows = len(grid)
    num_cols = len(grid[0]) if num_rows > 0 else 0
    for row in range(0, num_rows, 2):
        t = Text()
        for col in range(num_cols):
            r1, g1, b1 = grid[row][col]
            r2, g2, b2 = grid[row + 1][col] if row + 1 < num_rows else (0, 0, 0)
            bg1 = (r1 < bg_threshold and g1 < bg_threshold and b1 < bg_threshold)
            bg2 = (r2 < bg_threshold and g2 < bg_threshold and b2 < bg_threshold)

            if bg1 and bg2:
                t.append(' ')
            elif bg1 and not bg2:
                t.append('▄', style=Style(color=Color.from_rgb(r2, g2, b2)))
            elif not bg1 and bg2:
                t.append('▀', style=Style(color=Color.from_rgb(r1, g1, b1)))
            else:
                t.append('▀', style=Style(color=Color.from_rgb(r1, g1, b1), bgcolor=Color.from_rgb(r2, g2, b2)))
        lines.append(t)
    return Group(*lines)
